1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	
4	const BASE_PREMIUM: Record<string, number> = {
5	  sword: 100,
6	  amulet: 60,
7	  staff: 80,
8	  potion: 40,
9	  rune: 25,
10	};
11	
12	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
13	const BLOCK_SIZE = 3;
14	const BLOCK_PREMIUM = 60;
15	
16	type Item = { type: string };
17	type Scenario = {
18	  customer: { yearsWithMHPCO: number };
19	  steps: Array<{ op: "quote"; items: Item[] }>;
20	};
21	
22	const itemBase = (item: Item): number => BASE_PREMIUM[item.type];
23	
24	const itemsBase = (items: Item[]): number => {
25	  const components = items.filter((i) => COMPONENT_TYPES.has(i.type));
26	  const nonComponents = items.filter((i) => !COMPONENT_TYPES.has(i.type));
27	
28	  const groupedByType = new Map<string, number>();
29	  for (const c of components) {
30	    groupedByType.set(c.type, (groupedByType.get(c.type) ?? 0) + 1);
31	  }
32	
33	  let componentsBase = 0;
34	  for (const [type, count] of groupedByType) {
35	    if (count === BLOCK_SIZE) {
36	      componentsBase += BLOCK_PREMIUM;
37	    } else {
38	      componentsBase += count * BASE_PREMIUM[type];
39	    }
40	  }
41	
42	  const nonComponentsBase = nonComponents.reduce((sum, i) => sum + itemBase(i), 0);
43	  return componentsBase + nonComponentsBase;
44	};
45	
46	const applyItemSurcharges = (base: number): number =>
47	  base * (1 + FIRST_INSURANCE_SURCHARGE_RATE);
48	
49	const roundUpInFavorOfInsurer = (amount: number): number =>
50	  Math.ceil(Math.round(amount * 1e6) / 1e6);
51	
52	const quotePremium = (items: Item[]): number => {
53	  const premiumBeforeFee = applyItemSurcharges(itemsBase(items));
54	  return roundUpInFavorOfInsurer(premiumBeforeFee + PROCESSING_FEE);
55	};
56	
57	export const runScenario = (scenario: unknown): unknown => ({
58	  results: (scenario as Scenario).steps.map((step) => ({
59	    premium: quotePremium(step.items),
60	  })),
61	});
